const IDX_YAW = 45
const IDX_ROLL = 47
const IDX_CONF = 48

function predictRaw(f) {
  let s = BASELINE
  for (let t = 0; t < TREES.length; t++) {
    const tree = TREES[t]
    let ni = 0
    while (!tree[ni].l) {
      const v = f[FEATURE_NAMES[tree[ni].f]] || 0
      ni = v <= tree[ni].t ? tree[ni].le : tree[ni].ri
    }
    s += tree[ni].v
  }
  return Math.min(5, Math.max(1, s))
}
function poseGate(f) {
  const yaw = Math.abs(f[FEATURE_NAMES[IDX_YAW]] || 0)
  const roll = Math.abs(f[FEATURE_NAMES[IDX_ROLL]] || 0)
  const conf = f[FEATURE_NAMES[IDX_CONF]] || 5
  let gate = 1.0,
    warn = []
  if (yaw > 0.15) {
    gate *= 0.85
    warn.push('large_yaw')
  }
  if (Math.abs(roll) > 10) {
    gate *= 0.9
    warn.push('large_roll')
  }
  if (conf < 3) {
    gate *= 0.9
    warn.push('low_confidence')
  }
  return { gate, warn }
}
function predictScore(f) {
  const raw = predictRaw(f)
  const { gate, warn } = poseGate(f)
  // gate pulls toward neutral (3.0) but doesn't change raw label training
  const gated = 3.0 + (raw - 3.0) * gate
  return { score: Math.min(5, Math.max(1, gated)), raw, gate, warn }
}
function scoreTo100(s) {
  return ((s - 1) / 4) * 100
}
